(()=>{
 const bookings=[{id:'BKG-24081',room:'Kamar Deluxe 201',period:'1 Agu–31 Des 2026',type:'Bulanan',status:'Aktif',total:9250000,cancel:false},{id:'BKG-24062',room:'Daily Room D01',period:'18–20 Jul 2026',type:'Harian',status:'Selesai',total:550000,cancel:false},{id:'BKG-24040',room:'Kamar Standard 101',period:'1–30 Jul 2026',type:'Bulanan',status:'Dibatalkan',total:1350000,cancel:false},{id:'BKG-24090',room:'Studio Eksklusif 401',period:'1 Sep 2026–28 Feb 2027',type:'Bulanan',status:'Menunggu',total:19200000,cancel:true}];
 const bills=[{id:'INV-2026-0081',name:'Sewa Agustus 2026',amount:1850000,status:'Pending',date:'5 Agu 2026'},{id:'INV-2026-0072',name:'Deposit kamar',amount:500000,status:'Menunggu verifikasi',date:'1 Agu 2026'},{id:'INV-2026-0061',name:'Sewa Juli 2026',amount:1850000,status:'Lunas',date:'2 Jul 2026'},{id:'INV-2026-0050',name:'Sewa Juni 2026',amount:1850000,status:'Kedaluwarsa',date:'10 Jun 2026'}];
 const complaints=[{id:'KEL-081',title:'AC kurang dingin',cat:'Fasilitas kamar',status:'Diproses',priority:'Sedang'},{id:'KEL-063',title:'Lampu lorong mati',cat:'Area umum',status:'Selesai',priority:'Rendah'}];
 const announcements=[{title:'Pemeliharaan jaringan Wi-Fi',date:'5 Agu 2026',priority:true,summary:'Koneksi akan mengalami gangguan pada 8 Agustus.',body:'Pemeliharaan dijadwalkan pukul 01.00–03.00 WIB. Mohon simpan pekerjaan sebelum waktu tersebut.'},{title:'Jadwal pembersihan area bersama',date:'2 Agu 2026',summary:'Pembersihan rutin dilakukan setiap Selasa.',body:'Mohon tidak meninggalkan barang pribadi di dapur dan ruang bersama pada pukul 09.00–11.00 WIB.'},{title:'Pengingat pembayaran bulanan',date:'1 Agu 2026',summary:'Tagihan bulanan telah diterbitkan.',body:'Silakan periksa halaman Tagihan & Pembayaran dan selesaikan pembayaran sebelum tanggal jatuh tempo.'}];
 const activities=['Login dari perangkat Chrome · Hari ini, 08.14','Tagihan INV-2026-0081 diterbitkan · 5 Agu 2026','Status keluhan KEL-081 menjadi Diproses · 4 Agu 2026','Booking BKG-24081 dikonfirmasi · 1 Agu 2026','Bukti transfer deposit diunggah · 1 Agu 2026','Profil diperbarui · 30 Jul 2026','Login dari perangkat Android · 28 Jul 2026','Booking harian selesai · 20 Jul 2026','Pembayaran sewa Juli dikonfirmasi · 2 Jul 2026'];
 const statusClass=s=>s==='Lunas'||s==='Aktif'||s==='Selesai'?'green':s.includes('Menunggu')||s==='Diproses'?'amber':s==='Pending'?'blue':'red';
 const tableState=(normal,emptyText)=>T.state==='loading'?T.loading(3):T.state==='empty'?T.stateBox(emptyText,'Data akan muncul setelah tersedia.',false):T.state==='error'?T.stateBox('Data gagal dimuat','Periksa koneksi lalu coba kembali.'):normal;
 const modal=(id,html)=>{document.getElementById(id)?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog id="${id}"><div class="modal">${html}</div></dialog>`);const d=document.getElementById(id);d.querySelector('[data-close]')?.addEventListener('click',()=>d.close());d.showModal();return d};

 function dashboard(){
  if(T.state==='empty'){const labels=[['Booking aktif','Belum ada booking aktif'],['Masa sewa aktif','Belum ada masa sewa aktif'],['Tagihan','Tidak ada tagihan tertunda'],['Pembayaran','Belum ada pembayaran'],['Keluhan','Tidak ada keluhan aktif'],['Pengumuman','Belum ada pengumuman']];T.content.innerHTML=T.head('Ringkasan','Selamat datang kembali, Aulia.')+`<div class="grid g3">${labels.map(x=>`<div class="card widget"><p class="label">${x[0]}</p><p class="sub">${x[1]}</p></div>`).join('')}</div>`;return}
  T.content.innerHTML=T.head('Ringkasan','Selamat datang kembali, Aulia.')+tableState(`<div class="grid g3"><a class="card widget" href="booking.html"><p class="label">Booking aktif</p><p class="value">Kamar 201</p><p class="sub"><span class="dot green"></span>Sampai 31 Desember 2026</p></a><a class="card widget" href="booking.html"><p class="label">Masa sewa aktif</p><p class="value">148 hari</p><p class="sub">Sewa bulanan · Deluxe</p></a><a class="card widget" href="tagihan.html"><p class="label">Tagihan belum dibayar</p><p class="value">${T.money(1850000)}</p><p class="sub"><span class="dot amber"></span>Jatuh tempo 10 Agustus</p></a><a class="card widget" href="tagihan.html"><p class="label">Pembayaran terakhir</p><p class="value">${T.money(500000)}</p><p class="sub">Deposit · Menunggu verifikasi</p></a><a class="card widget" href="keluhan.html"><p class="label">Keluhan aktif</p><p class="value">1 keluhan</p><p class="sub">AC kurang dingin · Diproses</p></a><a class="card widget" href="pengumuman.html"><p class="label">Pengumuman terbaru</p><p class="value" style="font-size:18px">Pemeliharaan Wi-Fi</p><p class="sub">Diterbitkan 5 Agustus 2026</p></a></div>`,'Belum ada ringkasan aktif');
 }
 function booking(){
  const rows=bookings.map(b=>`<tr data-status="${b.status}"><td><strong>${b.id}</strong></td><td>${b.room}</td><td>${b.period}<br><small>${b.type}</small></td><td><span class="status"><i class="dot ${statusClass(b.status)}"></i>${b.status}</span></td><td>${T.money(b.total)}</td><td><button class="btn btn-line" data-booking="${b.id}">Detail</button></td></tr>`).join('');
  T.content.innerHTML=T.head('Booking Saya','Riwayat booking kamar Anda.')+`<div class="toolbar"><select class="select" data-booking-filter><option>Semua status</option><option>Aktif</option><option>Menunggu</option><option>Selesai</option><option>Dibatalkan</option></select></div><div data-booking-body>${tableState(`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Kamar</th><th>Jadwal</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,'Belum pernah booking')}</div>`;
  document.querySelector('[data-booking-filter]')?.addEventListener('change',e=>document.querySelectorAll('tbody tr').forEach(r=>r.classList.toggle('hidden',e.target.value!=='Semua status'&&r.dataset.status!==e.target.value)));
  document.querySelectorAll('[data-booking]').forEach(btn=>btn.onclick=()=>bookingDetail(bookings.find(x=>x.id===btn.dataset.booking)));
 }
 function bookingDetail(b){const d=modal('booking-detail',`<div class="modal-head"><div><p class="label">${b.id}</p><h2>${b.room}</h2></div><button class="close" data-close>×</button></div><div class="detail-list"><div class="detail-row"><span>Status</span><strong>${b.status}</strong></div><div class="detail-row"><span>Jadwal</span><strong>${b.period}</strong></div><div class="detail-row"><span>Tipe sewa</span><strong>${b.type}</strong></div><div class="detail-row"><span>Harga sewa</span><strong>${T.money(b.total-500000)}</strong></div><div class="detail-row"><span>Deposit</span><strong>${T.money(500000)}</strong></div><div class="detail-row"><span>Total</span><strong>${T.money(b.total)}</strong></div><div class="detail-row"><span>Invoice</span><a href="invoice.html?id=INV-2026-0081"><strong>INV-2026-0081</strong></a></div></div><div style="margin-top:22px"><button class="btn btn-red" data-cancel ${b.cancel?'':'disabled'}>${b.cancel?'Batalkan Booking':'Booking Tidak Dapat Dibatalkan'}</button>${!b.cancel?'<p class="sub" style="margin-top:8px">Status booking ini tidak memungkinkan pembatalan.</p>':''}</div>`);d.querySelector('[data-cancel]')?.addEventListener('click',()=>{if(confirm('Yakin ingin membatalkan booking ini?')){alert('Booking dibatalkan (simulasi).');d.close()}})}
 function tagihan(){const rows=bills.map(b=>`<tr><td><strong>${b.id}</strong><br><small>${b.name}</small></td><td>${b.date}</td><td>${T.money(b.amount)}</td><td><span class="status"><i class="dot ${statusClass(b.status)}"></i>${b.status}</span></td><td><button class="btn btn-line" data-bill="${b.id}">Detail</button></td></tr>`).join('');T.content.innerHTML=T.head('Tagihan & Pembayaran','Kelola invoice dan pembayaran Anda.')+tableState(`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Jatuh tempo</th><th>Jumlah</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,'Belum ada tagihan');document.querySelectorAll('[data-bill]').forEach(btn=>btn.onclick=()=>billDetail(bills.find(x=>x.id===btn.dataset.bill)))}
 function billDetail(b){const d=modal('bill-detail',`<div class="modal-head"><div><p class="label">${b.id}</p><h2>${b.name}</h2></div><button class="close" data-close>×</button></div><div data-upload-alert></div><div class="detail-list"><div class="detail-row"><span>Sewa kamar</span><strong>${T.money(b.amount)}</strong></div><div class="detail-row"><span>Biaya layanan</span><strong>Rp0</strong></div><div class="detail-row"><span>Total</span><strong>${T.money(b.amount)}</strong></div><div class="detail-row"><span>Status</span><strong data-payment-status>${b.status}</strong></div></div><h3>Riwayat status</h3><div class="timeline"><div><p>Invoice diterbitkan</p><small>5 Agu 2026, 08.00</small></div><div><p>Menunggu pembayaran</p><small>5 Agu 2026, 08.01</small></div></div><h3>Metode pembayaran</h3><div class="actions"><button class="btn btn-blue" data-pay>Bayar Sekarang</button><a class="btn btn-line" href="invoice.html?id=${b.id}">Lihat Invoice</a><button class="btn btn-line" data-download>Unduh Invoice</button></div><div class="card soft" style="margin-top:16px"><strong>Transfer manual</strong><p class="sub">Bank BCA · 1234567890 · Manzsa Residence</p><div class="field" style="margin-top:12px"><label>Upload bukti (JPG/PNG/PDF, maks. 2 MB)</label><input type="file" data-proof accept=".jpg,.jpeg,.png,.pdf"><span class="error-text" data-file-error></span></div><button class="btn btn-dark" data-upload>Upload Bukti</button></div>`);d.querySelector('[data-pay]').onclick=()=>alert('Membuka pembayaran online (simulasi).');d.querySelector('[data-download]').onclick=()=>alert('Invoice PDF diunduh (simulasi).');d.querySelector('[data-upload]').onclick=()=>{const f=d.querySelector('[data-proof]').files[0],err=d.querySelector('[data-file-error]');if(!f){err.textContent='Pilih file terlebih dahulu.';return}if(!['image/jpeg','image/png','application/pdf'].includes(f.type)){err.textContent='Tipe file harus JPG, PNG, atau PDF.';return}if(f.size>2*1024*1024){err.textContent='Ukuran file maksimal 2 MB.';return}err.textContent='';d.querySelector('[data-payment-status]').textContent='Menunggu verifikasi';d.querySelector('[data-upload-alert]').className='alert success';d.querySelector('[data-upload-alert]').textContent='Bukti transfer berhasil diunggah.'}}
 function invoice(){const id=new URLSearchParams(location.search).get('id')||'INV-2026-0081',found=bills.find(x=>x.id===id);if(T.state==='loading'){T.content.innerHTML=T.head('Invoice','Memuat dokumen...')+T.loading(2);return}if(T.state==='error'||!found){T.content.innerHTML=T.head('Invoice','Dokumen pembayaran')+T.stateBox('Invoice tidak ditemukan','Nomor invoice tidak valid atau data sudah tidak tersedia.');return}T.content.innerHTML=T.head('Invoice','Dokumen pembayaran',`<button class="btn btn-dark" onclick="alert('PDF diunduh (simulasi)')">Unduh PDF</button>`)+`<article class="invoice"><div class="invoice-head"><div><h2>MANZSA RESIDENCE</h2><p class="sub">Jl. Contoh Residence No. 21, Jakarta<br>halo@manzsaresidence.id · +62 812-3456-7890</p></div><div><p class="label">Nomor invoice</p><strong>${id}</strong><p class="sub">Dibuat 5 Agustus 2026</p></div></div><div class="grid g2" style="margin-bottom:26px"><div><p class="label">Ditagihkan kepada</p><strong>Aulia Rahman</strong><p class="sub">Tenant Kamar Deluxe 201</p></div><div><p class="label">Detail sewa</p><strong>Sewa bulanan</strong><p class="sub">1–31 Agustus 2026</p></div></div><div class="detail-list"><div class="detail-row"><span>Sewa Kamar Deluxe 201</span><strong>${T.money(found.amount)}</strong></div><div class="detail-row"><span>Biaya layanan</span><strong>Rp0</strong></div><div class="detail-row"><span>Metode pembayaran</span><strong>Transfer bank</strong></div><div class="detail-row"><span>Status</span><strong>${found.status}</strong></div><div class="detail-row"><span>Tanggal dibayar</span><strong>${found.status==='Lunas'?'2 Juli 2026':'—'}</strong></div></div><div class="invoice-total"><span>Total</span><span>${T.money(found.amount)}</span></div></article>`}
 function keluhan(){const rows=complaints.map(c=>`<tr><td><strong>${c.id}</strong></td><td>${c.title}<br><small>${c.cat}</small></td><td>${c.priority}</td><td><span class="status"><i class="dot ${statusClass(c.status)}"></i>${c.status}</span></td><td><button class="btn btn-line" data-complaint="${c.id}">Detail</button></td></tr>`).join('');T.content.innerHTML=T.head('Keluhan','Laporkan dan pantau kendala hunian.',`<button class="btn btn-blue" data-new-complaint>Buat Keluhan Baru</button>`)+tableState(`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Keluhan</th><th>Prioritas</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,'Belum ada keluhan');document.querySelector('[data-new-complaint]')?.addEventListener('click',complaintForm);document.querySelectorAll('[data-complaint]').forEach(b=>b.onclick=()=>complaintDetail(complaints.find(x=>x.id===b.dataset.complaint)))}
 function complaintForm(){const d=modal('complaint-form',`<div class="modal-head"><h2>Buat Keluhan Baru</h2><button class="close" data-close>×</button></div><div data-alert></div><form class="form"><div class="field"><label>Judul</label><input class="input" name="title"><span class="error-text"></span></div><div class="grid g2"><div class="field"><label>Kategori</label><select class="select" name="category"><option value="">Pilih kategori</option><option>Fasilitas kamar</option><option>Area umum</option><option>Keamanan</option></select><span class="error-text"></span></div><div class="field"><label>Prioritas</label><select class="select" name="priority"><option>Rendah</option><option>Sedang</option><option>Tinggi</option></select><span class="error-text"></span></div></div><div class="field"><label>Deskripsi</label><textarea class="textarea" rows="5" name="description"></textarea><span class="error-text"></span></div><div class="field"><label>Kamar terkait (opsional)</label><select class="select"><option>Kamar Deluxe 201</option></select></div><div class="field"><label>Lampiran foto (opsional)</label><input type="file" accept="image/*"></div><button class="btn btn-dark">Kirim Keluhan</button></form>`);const f=d.querySelector('form');f.onsubmit=e=>{e.preventDefault();let ok=true;[['title',3],['description',10]].forEach(([n,min])=>{const i=f[n],err=i.parentElement.querySelector('.error-text');err.textContent=i.value.trim().length>=min?'':`Minimal ${min} karakter`;if(err.textContent)ok=false});const cat=f.category,ce=cat.parentElement.querySelector('.error-text');ce.textContent=cat.value?'':'Kategori wajib dipilih';if(!cat.value)ok=false;if(ok){d.querySelector('[data-alert]').className='alert success';d.querySelector('[data-alert]').textContent='Keluhan berhasil dikirim (simulasi).';f.reset()}}}
 function complaintDetail(c){modal('complaint-detail',`<div class="modal-head"><div><p class="label">${c.id} · ${c.cat}</p><h2>${c.title}</h2></div><button class="close" data-close>×</button></div><p>AC kamar terasa kurang dingin sejak dua hari terakhir meskipun telah diatur pada suhu rendah.</p><img class="preview" src="https://images.unsplash.com/photo-1631545806609-4b65b2ff0044?q=80&w=500&auto=format&fit=crop" alt="Lampiran keluhan"><h3>Respons owner</h3><div class="alert success">Teknisi dijadwalkan datang besok pukul 10.00 WIB.</div><h3>Riwayat status</h3><div class="timeline"><div><p>Keluhan dibuat</p><small>3 Agu 2026</small></div><div><p>Status menjadi Diproses</p><small>4 Agu 2026</small></div></div>`)}
 function pengumuman(){T.content.innerHTML=T.head('Pengumuman','Informasi terbaru untuk penghuni.')+tableState(`<div class="grid g2">${announcements.map(a=>`<article class="card announcement"><p class="${a.priority?'priority':'label'}">${a.priority?'Prioritas · ':''}${a.date}</p><h3>${a.title}</h3><p class="sub">${a.summary}</p><div class="body"><hr>${a.body}</div></article>`).join('')}</div>`,'Belum ada pengumuman aktif');document.querySelectorAll('.announcement').forEach(x=>x.onclick=()=>x.classList.toggle('open'))}
 function aktivitas(){let count=5;const draw=()=>{document.querySelector('[data-activity-list]').innerHTML=activities.slice(0,count).map((a,i)=>`<div class="card" style="display:flex;gap:14px"><span class="dot ${i<2?'blue':'green'}" style="margin-top:7px"></span><div>${a}</div></div>`).join('');document.querySelector('[data-more]').classList.toggle('hidden',count>=activities.length)};T.content.innerHTML=T.head('Aktivitas','Riwayat aktivitas terbaru akun Anda.')+tableState(`<div class="grid" data-activity-list></div><div style="text-align:center;margin-top:20px"><button class="btn btn-dark" data-more>Muat Lebih Banyak</button></div>`,'Belum ada aktivitas');if(T.state==='normal'){draw();document.querySelector('[data-more]').onclick=()=>{count+=4;draw()}}}
 function profil(){if(T.state==='loading'){T.content.innerHTML=T.head('Profil','Memuat profil...')+T.loading(2);return}if(T.state==='error'){T.content.innerHTML=T.head('Profil','Kelola data akun Anda.')+T.stateBox('Profil gagal dimuat','Silakan coba kembali.');return}T.content.innerHTML=T.head('Profil','Kelola data pribadi dan dokumen Anda.')+`<div class="card"><div data-alert></div><form class="form" data-profile><div style="display:flex;align-items:center;gap:16px"><img class="avatar" style="width:72px;height:72px" data-avatar src="" alt="AR"><div class="field"><label>Foto profil</label><input type="file" name="photo" accept="image/*"></div></div><div class="grid g2"><div class="field"><label>Nama lengkap</label><input class="input" name="name" value="Aulia Rahman"><span class="error-text"></span></div><div class="field"><label>Email</label><input class="input" name="email" value="aulia@example.com"><span class="error-text"></span></div><div class="field"><label>Nomor telepon</label><input class="input" name="phone" value="081234567890"><span class="error-text"></span></div><div class="field"><label>Kontak darurat</label><input class="input" name="emergency" value="081298765432"><span class="error-text"></span></div></div><div class="field"><label>Alamat</label><textarea class="textarea" name="address">Jl. Contoh No. 10, Jakarta</textarea><span class="error-text"></span></div><div class="grid g2"><div class="field"><label>Nomor identitas (opsional)</label><input class="input" name="identity"></div><div class="field"><label>Dokumen identitas (opsional)</label><input type="file" name="document" accept=".jpg,.jpeg,.png,.pdf"><small data-document></small></div></div><button class="btn btn-dark">Simpan Perubahan</button></form></div>`;const f=document.querySelector('[data-profile]');f.photo.onchange=()=>{const file=f.photo.files[0];if(file)document.querySelector('[data-avatar]').src=URL.createObjectURL(file)};f.document.onchange=()=>document.querySelector('[data-document]').textContent=f.document.files[0]?.name||'';f.onsubmit=e=>{e.preventDefault();let ok=true;[['name',3],['phone',10],['emergency',10],['address',8]].forEach(([n,min])=>{const i=f[n],er=i.parentElement.querySelector('.error-text');er.textContent=i.value.trim().length>=min?'':`Minimal ${min} karakter`;if(er.textContent)ok=false});const ee=f.email.parentElement.querySelector('.error-text');ee.textContent=/^\S+@\S+\.\S+$/.test(f.email.value)?'':'Email tidak valid';if(ee.textContent)ok=false;if(ok){const b=f.querySelector('button');b.disabled=true;b.textContent='Menyimpan...';setTimeout(()=>{b.disabled=false;b.textContent='Simpan Perubahan';document.querySelector('[data-alert]').className='alert success';document.querySelector('[data-alert]').textContent='Profil berhasil diperbarui (simulasi).'},600)}}}
 const renders={dashboard,booking,tagihan,invoice,keluhan,pengumuman,aktivitas,profil};window.renderTenant=()=>renders[T.page]?.();renderTenant();
})();
